import { ref } from 'vue';
import axios from 'axios';
export default {
  __name: 'StartContainerDialog',
  setup(__props, {
    expose: __expose
  }) {
    const dialogVisible = ref(false);
    const form = ref({
      name: ''
    });

    // 打开弹窗
    const openDialog = () => {
      form.value.name = '';
      dialogVisible.value = true;
    };

    // 提交启动请求
    const submitStart = async () => {
      if (!form.value.name) {
        alert('请输入容器名称');
        return;
      }
      try {
        const response = await axios.post(`http://localhost:8081/container/start/${encodeURIComponent(form.value.name)}`);
        dialogVisible.value = false;
        alert(`启动成功：${response.data}`);
      } catch (error) {
        console.error('启动容器出错：', error);
        alert('启动失败：' + (error.response?.data || error.message));
      }
    };

    // 向父组件暴露方法
    __expose({
      openDialog
    });
    const __returned__ = {
      dialogVisible,
      form,
      openDialog,
      submitStart,
      ref,
      get axios() {
        return axios;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
